"""Sigles propres à B37 — Candidose (I-03-Infectiologie)."""
from cardio_1 import a, G

FUN = '<p>Source : <a href="https://doi.org/10.1093/ofid/ofab471" target="_blank" rel="noopener">Adam KM et al., Open Forum Infect Dis 2021;8:ofab471</a>.</p>'
a('FUNGINOS', [('FUNG', 'FUNGal (fongique)'), ('I', 'Infection'), ('N', 'Network (réseau)'), ('O', 'Of (de)'), ('S', 'Switzerland (Suisse)')], 'Réseau suisse des infections fongiques (Fungal Infection Network of Switzerland)', '<p>Réseau des hôpitaux et laboratoires suisses qui surveille les infections fongiques invasives ; son étude de 2004 à 2018 porte sur 2273 candidémies.</p>' + FUN)
if 'P450' not in G: a('P450', [('P', 'Pigment'), ('450', 'pic d’absorption à 450 nanomètres du complexe avec le monoxyde de carbone')], 'Cytochrome P450', '<p>Famille d’enzymes, surtout hépatiques, qui métabolisent de nombreux médicaments ; les azolés inhibent à la fois l’enzyme fongique de synthèse de l’ergostérol et le CYP3A4 humain, d’où leurs interactions.</p>')
